package run.ikaros.sharing; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/rooms/{roomId}/events") public class RoomEventController{private final RoomEventService service;public RoomEventController(RoomEventService s){service=s;}@PostMapping public Mono<RoomEventView> append(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID roomId,@Valid@RequestBody AppendRoomEventRequest r){return service.append(a,roomId,r);}@GetMapping public Flux<RoomEventView> replay(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID roomId,@RequestParam(defaultValue="0")long afterSequence){return service.replay(a,roomId,afterSequence);}}
